import 'dotenv/config';
import { defineConfig } from 'prisma/config';

const PRISMA_GENERATE_FALLBACK_DATABASE_URL =
  'postgresql://prisma:prisma@localhost:5432/prisma?schema=public';

const isPrismaGenerateCommand = process.argv.includes('generate');

const databaseUrl =
  process.env.DATABASE_URL ??
  (isPrismaGenerateCommand ? PRISMA_GENERATE_FALLBACK_DATABASE_URL : undefined);

if (!databaseUrl) {
  throw new Error('DATABASE_URL is required for Prisma commands other than generate.');
}

export default defineConfig({
  schema: 'prisma/schema.prisma',
  migrations: {
    path: 'prisma/migrations',
    seed: 'npx tsx prisma/seed.ts',
  },
  datasource: {
    url: databaseUrl,
  },
});
